// Parse response and group by practice
const items = $input.all();
let automations = [];

// Log the raw response for debugging
console.log('Raw response:', JSON.stringify(items));

// n8n returns each row from Supabase as a separate item
// So we need to extract the json from each item
if (items && items.length > 0) {
  // Check if the first item is already an automation object
  if (items[0].json && items[0].json.queue_id) {
    // Each item is an automation, collect them all
    automations = items.map(item => item.json);
  } else {
    // Try other formats just in case
    const response = items[0].json;

    if (Array.isArray(response)) {
      automations = response;
    } else if (response && typeof response === 'object') {
      // Log the response structure
      console.log('Response type:', typeof response);
      console.log('Response keys:', Object.keys(response));

      // Check various possible response formats
      if (Array.isArray(response.data)) {
        automations = response.data;
      } else if (Array.isArray(response.result)) {
        automations = response.result;
      }
    }
  }
}

console.log(`Found ${automations.length} pending automations`);

// If no automations, return empty
if (automations.length === 0) {
  return [{ json: { message: 'No pending automations found' } }];
}

// Map practice IDs to Gmail credential IDs
const practiceCredentialMap = {
  'ffed1160-00ec-4c4f-8810-913a24348d90': 'uA0l39VD4cMHN9cC', // NewCharm
  'onehealth_practice_id': 'HrTrOqI74H5m5dyg', // OneHealth - replace with actual practice ID
  // Add more practice mappings here as needed
};

// Group by practice
const practiceGroups = {};
automations.forEach(automation => {
  const practiceId = automation.practice_id;
  if (!practiceGroups[practiceId]) {
    practiceGroups[practiceId] = {
      practice_id: practiceId,
      practice_name: automation.practice_name || 'Unknown Practice',
      gmail_credential_id: practiceCredentialMap[practiceId] || null,
      automations: []
    };
  }
  practiceGroups[practiceId].automations.push(automation);
});

// Return groups
return Object.values(practiceGroups).map(group => ({ json: group }));

// Process NewCharm automations in parallel
const automations = $json.automations || [];

// Separate SMS and Email automations based on enabled flags
const smsAutomations = automations.filter(a => a.sms_enabled);
const emailAutomations = automations.filter(a => a.email_enabled);

console.log(`NewCharm: ${smsAutomations.length} SMS, ${emailAutomations.length} Email`);

// Create outputs for parallel processing
const outputs = [];

if (smsAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',
      type: 'SMS',
      automations: smsAutomations
    }
  });
}

if (emailAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',  
      type: 'EMAIL',
      automations: emailAutomations
    }
  });
}

// If no automations, return empty result
if (outputs.length === 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',
      type: 'NONE',
      automations: []
    }
  });
}

return outputs;

// Process SMS automations one by one
const smsData = $json;
console.log('NewCharm Prepare SMS - Input:', JSON.stringify(smsData));

return smsData.automations.map((automation, index) => {
  console.log(`Preparing SMS ${index}:`, {
    queue_id: automation.queue_id,
    automation_id: automation.automation_id,
    patient_phone: automation.payload?.patientPhone || automation.payload?.patient_phone || automation.payload?.phone
  });

  return {
    json: {
      practiceId: smsData.practice_id,
      recipientPhone: automation.payload?.patientPhone || automation.payload?.patient_phone || automation.payload?.phone || '',
      messageContent: (automation.sms_template || '')
        .replace(/\{\{patientName\}\}/g, automation.payload?.patientName || automation.payload?.patient_name || '')
        .replace(/\{\{practiceName\}\}/g, automation.practice_name || smsData.practice_name || '')
        .replace(/\{\{practicePhone\}\}/g, automation.practice_phone || '')
        .replace(/\{\{practiceEmail\}\}/g, automation.practice_email || ''),
      messageType: 'automation',
      patientId: automation.payload?.patient_id || automation.payload?.patientId || null,
      metadata: {
        automation_id: automation.automation_id,
        trigger_type: automation.trigger_type,
        queue_id: automation.queue_id,
        practice_id: smsData.practice_id
      }
    }
  };
});

// Process emails one by one
const emailAutomations = $json.automations || [];
return emailAutomations.map(automation => {
  // Extract recipient email from payload
  const recipientEmail = automation.payload?.patientEmail || 
                        automation.payload?.patient_email || 
                        automation.payload?.email || 
                        '';

  // Replace template variables
  const replacePlaceholders = (template, data) => {
    if (!template) return '';
    return template
      .replace(/{{patientName}}/g, data.patientName || data.patient_name || '')
      .replace(/{{practiceName}}/g, data.practiceName || data.practice_name || $json.practice_name || '')
      .replace(/{{practicePhone}}/g, data.practicePhone || data.practice_phone || automation.practice_phone || '')
      .replace(/{{practiceEmail}}/g, data.practiceEmail || data.practice_email || automation.practice_email || '');
  };

  const subject = replacePlaceholders(automation.email_subject, automation.payload);
  const body = replacePlaceholders(automation.email_body, automation.payload);

  return {
    json: {
      to: recipientEmail,
      subject: subject,
      body: body,
      automation_id: automation.queue_id,
      practice_id: $json.practice_id,
      practice_name: $json.practice_name
    }
  };
});

// Collect NewCharm results with comprehensive logging
const results = $input.all();
const successItems = [];

console.log('Collect NewCharm - Raw Results:', JSON.stringify(results));

results.forEach((result, index) => {
  const data = result.json;
  console.log(`Processing result ${index}:`, JSON.stringify(data));

  if (data.automation_id) {
    // Email result from Gmail node
    console.log('Found email result with automation_id:', data.automation_id);
    successItems.push({
      id: data.automation_id,
      type: 'EMAIL',
      practice_id: data.practice_id,
      status: 'completed'
    });
  } else if (data.success && data.logId) {
    // SMS result with queue_id from gateway
    console.log('Found SMS result:', {
      logId: data.logId,
      queue_id: data.queue_id,
      practiceId: data.practiceId || data.practice_id
    });

    if (data.queue_id) {
      console.log('Using queue_id for status update:', data.queue_id);
      successItems.push({
        id: data.queue_id,
        type: 'SMS',
        practice_id: data.practice_id || data.practiceId,
        status: 'completed'
      });
    } else {
      console.error('SMS result missing queue_id!', data);
      // Fallback to logId if queue_id is missing
      successItems.push({
        id: data.logId,
        type: 'SMS', 
        practice_id: data.practice_id || data.practiceId,
        status: 'completed',
        error: 'Missing queue_id, using logId as fallback'
      });
    }
  } else {
    console.log('Unhandled result type:', JSON.stringify(data));
  }
});

console.log('Collected success items:', JSON.stringify(successItems));

// Always return at least one item to continue workflow
if (successItems.length === 0) {
  console.log('No success items found, returning empty message');
  return [{ json: { message: 'No items to process', count: 0 } }];
}

return successItems.map(item => ({ json: item }));

// Handle unknown practices dynamically
const practiceData = $json;

console.log('Processing unknown practice:', {
  practice_id: practiceData.practice_id,
  practice_name: practiceData.practice_name,
  has_gmail_credentials: !!practiceData.gmail_credential_id
});

// For unknown practices, we can still process SMS through centralized gateway
// But email will fail if no Gmail credentials are mapped

const automations = practiceData.automations || [];
const smsAutomations = automations.filter(a => a.sms_enabled);
const emailAutomations = automations.filter(a => a.email_enabled);

const outputs = [];

// Process SMS through centralized gateway
if (smsAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'SMS',
      automations: smsAutomations,
      is_unknown_practice: true
    }
  });
}

// For emails, mark as failed if no credentials
if (emailAutomations.length > 0 && !practiceData.gmail_credential_id) {
  const failedEmails = emailAutomations.map(automation => ({
    id: automation.queue_id,
    status: 'failed',
    error_message: 'No Gmail credentials configured for this practice'
  }));

  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'FAILED_EMAIL',
      failed_items: failedEmails
    }
  });
}

if (outputs.length === 0) {
  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'NONE',
      automations: []
    }
  });
}

return outputs;

// Prepare status updates with comprehensive logging
const allItems = $input.all();
const updates = [];

console.log('Prepare Updates - Raw Input:', JSON.stringify(allItems));

allItems.forEach((item, index) => {
  console.log(`Processing item ${index}:`, JSON.stringify(item.json));

  if (item.json.id || item.json.queue_id) {
    const updateId = item.json.id || item.json.queue_id;
    console.log(`Creating update for ID: ${updateId}`);

    updates.push({
      id: updateId,
      status: item.json.status || 'completed',
      completed_at: new Date().toISOString(),
      error_message: item.json.error_message || null
    });
  } else if (item.json.failed_items) {
    // Handle failed email items
    item.json.failed_items.forEach(failedItem => {
      console.log('Processing failed item:', failedItem);
      updates.push({
        id: failedItem.id,
        status: failedItem.status,
        completed_at: new Date().toISOString(),
        error_message: failedItem.error_message
      });
    });
  } else {
    console.log('Item has no ID or queue_id, skipping:', JSON.stringify(item.json));
  }
});

console.log(`Updating ${updates.length} automation statuses`);
console.log('Updates to be applied:', JSON.stringify(updates));

return updates.map(update => ({ json: update }));
